INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT144-S4-Q3$batch13$, 144, 4, 3, $batch13$Paradox$batch13$, $batch13$The official listing of an animal species as endangered triggers the enforcement of legal safeguards designed to protect endangered species, such as tighter animal export and trade restrictions and stronger antipoaching laws. Nevertheless, there have been many cases in which the decline in the wild population of a species was more rapid after that species was listed as endangered than before it was so listed.$batch13$, $batch13$Which one of the following, if true, does most to account for the increase in the rate of population decline described above?$batch13$, $batch13$D$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=144 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q3$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$The process of officially listing a species as endangered can take many years.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$Public campaigns to save endangered animal species often focus only on those species that garner the public’s affection.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$The number of animal species listed as endangered has recently increased dramatically.$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$Animals are more desirable to collectors when they are perceived to be rare.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$Poachers find it progressively more difficult to locate animals of a particular species as that species’ population declines.$batch13$, $batch13$Opposite$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q3$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Fact$batch13$, $batch13$Listing a species as endangered brings stronger protections, such as trade limits and antipoaching laws.$batch13$), (1, $batch13$Fact$batch13$, $batch13$Many species declined faster after being listed than before.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$Protections should slow the decline. Something about being listed must make things worse, enough to outweigh the new protections.$batch13$), (3, $batch13$Goal$batch13$, $batch13$Find a way that being listed increases pressure on the species.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT144-S4-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$A slow listing process doesn't explain a faster decline after listing.$batch13$), ($batch13$B$batch13$, $batch13$Which species campaigns favor doesn't explain why decline speeds up after listing.$batch13$), ($batch13$C$batch13$, $batch13$More species being listed doesn't explain why any one species declines faster.$batch13$), ($batch13$D$batch13$, $batch13$Listing tells collectors the animals are rare, which makes them more desirable. More demand drives more poaching.$batch13$), ($batch13$E$batch13$, $batch13$If poachers find rare animals harder to locate, decline should slow.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT144-S4-Q3$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
